17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().replaceAll("\\D", "");
105	        if (telephone.length() != 10) {
106	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
107	        }
108	        owner.setTelephone(telephone);
109	        this.clinicService.saveOwner(owner);
110	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
111	        headers.setLocation(UriComponentsBuilder.newInstance()
112	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
113	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
119	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
120	        if (currentOwner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        currentOwner.setAddress(ownerFieldsDto.getAddress());
124	        currentOwner.setCity(ownerFieldsDto.getCity());
125	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
126	        currentOwner.setLastName(ownerFieldsDto.getLastName());
127	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
128	        this.clinicService.saveOwner(currentOwner);
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Transactional
134	    @Override
135	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
136	        Owner owner = this.clinicService.findOwnerById(ownerId);
137	        if (owner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        this.clinicService.deleteOwner(owner);
141	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
147	        Owner owner = this.clinicService.findOwnerById(ownerId);
148	        if (owner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        HttpHeaders headers = new HttpHeaders();
152	        Pet pet = petMapper.toPet(petFieldsDto);
153	        owner.setId(ownerId);
154	        pet.setOwner(owner);
155	        pet.getType().setName(null);
156	        this.clinicService.savePet(pet);
157	        PetDto petDto = petMapper.toPetDto(pet);
158	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
159	            .buildAndExpand(pet.getId()).toUri());
160	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
166	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
167	        if (currentOwner != null) {
168	            Pet currentPet = this.clinicService.findPetById(petId);
169	            if (currentPet != null) {
170	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
171	                currentPet.setName(petFieldsDto.getName());
172	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
173	                this.clinicService.savePet(currentPet);
174	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
175	            }
176	        }
177	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
183	        HttpHeaders headers = new HttpHeaders();
184	        Visit visit = visitMapper.toVisit(visitFieldsDto);
185	        Pet pet = new Pet();
186	        pet.setId(petId);
187	        visit.setPet(pet);
188	        this.clinicService.saveVisit(visit);
189	        VisitDto visitDto = visitMapper.toVisitDto(visit);
190	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
191	            .buildAndExpand(visit.getId()).toUri());
192	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
193	    }
194	
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
199	        Owner owner = this.clinicService.findOwnerById(ownerId);
200	        if (owner != null) {
201	            Pet pet = owner.getPet(petId);
202	            if (pet != null) {
203	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
204	            }
205	        }
206	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	    }
208	}
